/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_COVERAGE_PARAMETER
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_COVERAGE   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_delta3
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_COVERAGE_HK
   hashdiff    : SAT_COVERAGE_PARAMETER_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_COVERAGE|' || (HUB_COVERAGE_BK__COVER_CODE))) as HUB_COVERAGE_HK
        , COVER_PARAM as PARAMETER_REFERENCE
        , COVER_VALUE as PARAMETER_VALUE
        , 'BJAZ_STARPKG_COVER_MST' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_starpkg_cover_mst') }}
    where (nullif(trim(COVER_CODE),'')) is not null
),

resolved as (
    select
        HUB_COVERAGE_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PARAMETER_REFERENCE end) as PARAMETER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PARAMETER_VALUE end) as PARAMETER_VALUE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_COVERAGE_HK
),

hashed as (
    select
        *,
        case when PARAMETER_REFERENCE is not null or PARAMETER_VALUE is not null
                     then md5(upper(coalesce(cast(PARAMETER_REFERENCE as varchar), '') || '|' || coalesce(cast(PARAMETER_VALUE as varchar), '')))
                end as SAT_COVERAGE_PARAMETER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_COVERAGE_HK is not null
  and SAT_COVERAGE_PARAMETER_HASHDIFF is not null
